<?php

declare(strict_types=1);

namespace App\Services\Entrepreneurs\ReleaseGate;

final class RuleCatalogue
{
    // Nine phase-2 rules exchanged their placeholder input lists for the facts
    // their implementations actually read. The declared inputs are part of what
    // a recorded risk decision was taken against, so the version moves with them.
    public const VERSION = '2026-11-07.1';

    /** @return list<RuleDefinition> */
    public static function all(): array
    {
        return [
            new RuleDefinition('PM-01', 'Profitability claims', 'plan_vs_model', ['plan.profitability', 'model.profitability'], 'Every rendered profitability/break-even claim uses a current answer, names its measure (monthly operating break-even, annual profit or cumulative cash) and agrees with the matching model fact and period. Conflicting rendered versions fail; an unidentifiable measure is Cannot verify', Severity::Block, 1, false),
            new RuleDefinition('PM-02', 'Owner pay', 'plan_vs_model', ['plan.owner_pay', 'model.owner_pay'], 'Current and staged owner pay, frequency conversions, effective dates and triggers reconcile within the plan and to the monthly model schedule. A yearly average cannot stand in for a current rate without a labelled schedule', Severity::Block, 1, false),
            new RuleDefinition('PM-03', 'Opening cash', 'plan_vs_model', ['plan.opening_cash', 'model.opening_cash', 'cash.roll_forward'], 'Opening cash reconciles on the same date, currency, account and restriction basis within the configured tolerance (default 1%). Different dates/bases require a documented roll-forward; an earlier date is not an exemption', Severity::Block, 1, false),
            new RuleDefinition('PM-04', 'Stream capacity', 'plan_vs_model', ['stream.units', 'stream.price', 'stream.capacity', 'stream.revenue', 'stream.membership'], 'Each stream\'s delivery volume and revenue fit its documented unit, price and capacity schedule; compare total revenue to a single-stream ceiling only after base-case membership is established. Missing stream allocations or unit definitions are Cannot verify', Severity::Block, 1, false),
            new RuleDefinition('PM-05', 'Revenue ramp', 'plan_vs_model', ['plan.ramp', 'model.ramp', 'plan.start_period', 'model.start_period', 'stream.membership'], 'The model ramp for the same included streams and forecast start period matches the current plan schedule within the stated currency/display tolerance', Severity::Block, 2, false),
            new RuleDefinition('PM-06', 'Stream membership', 'plan_vs_model', ['stream.revenue', 'stream.membership', 'plan.stream_membership', 'model.base_revenue'], 'Every stream has explicit base/upside membership, and monthly base totals equal only included streams. Membership agrees with the current plan; missing flags or contributions are Cannot verify', Severity::Block, 2, false),
            new RuleDefinition('PM-07', 'Margin target', 'plan_vs_model', ['plan.margin_target', 'model.npbt_margin', 'plan.margin_explanation'], 'Compare actual model NPBT percentage with the stated target on a named period and basis; flag an unexplained variance or unspecified target period. A target is not a command to force the forecast into that range', Severity::Review, 1, false),
            new RuleDefinition('PM-08', 'Profit allocation', 'plan_vs_model', ['allocation.policy', 'allocation.amount', 'allocation.trigger', 'allocation.schedule', 'allocation.duplicate_line'], 'Giving, reinvestment and owner-distribution policies have explicit amounts/triggers and cash schedules, or a visible statement that they are excluded/conditional. Do not double-count reinvestment already in cost or capex lines', Severity::Review, 2, false),
            new RuleDefinition('PM-09', 'Committed costs', 'plan_vs_model', ['plan.commitment', 'budget.cost_mapping'], 'A committed in-scope plan cost at or above $1,000 has a mapped budget/actuals line and timing; a discretionary item can be explicitly deferred/excluded with the plan claim updated. A missing quantified commitment is Block; unpriced/unclear-scope items and smaller costs require Review, not an invented zero', Severity::Block, 1, false),
            new RuleDefinition('PM-10', 'Runway definition', 'plan_vs_model', ['runway.months', 'runway.start_cash', 'runway.includes_receipts', 'runway.includes_owner_pay', 'model.runway_months'], 'Every runway claim names its start cash, period, cost basis and whether it includes future receipts and owner pay. Compare like measures; label and reconcile essential-cost/no-sales runway separately from forecast cash runway', Severity::Review, 2, false),
            new RuleDefinition('PM-11', 'Shared founder capacity', 'plan_vs_model', ['capacity.available_hours', 'stream.units', 'stream.membership', 'stream.delivery_hours_per_unit', 'stream.preparation_hours_per_unit', 'capacity.provider', 'provider.capacity_hours', 'provider.start', 'provider.cost', 'provider.no_cost_basis'], 'Aggregate founder delivery and preparation time across included streams fits one shared time budget; additional delivery has a specified provider, capacity, timing and cost or a documented no-cost basis. Missing unit-to-time conversions are Cannot verify', Severity::Block, 2, false),
            new RuleDefinition('PM-12', 'Funding position', 'plan_vs_model', ['plan.funding_position', 'model.cash_deficit', 'model.reserve_gap', 'model.external_request', 'funding.provenance'], 'Funding-position claims reconcile to named sources, cash deficit, reserve-target shortfall and any external request. Unknown/double-counted sources or a self-funded claim relying on uncovered cash deficits block. A reserve-only gap is Review with a disclosed action/acceptance, not automatically borrowing or a false self-funded claim', Severity::Block, 1, false),
            new RuleDefinition('MI-01', 'Cash ledger', 'model_integrity', ['cash.opening', 'cash.movement', 'cash.closing', 'ledger.amount', 'ledger.category', 'ledger.date', 'ledger.source'], 'Every closing cash balance equals opening cash plus net movement; movement equals customer receipts plus other operating receipts and financing inflows, less operating payments, cash tax/GST, capex, principal repayments and distributions. Consecutive balances and annual totals reconcile; every movement has a ledger category, date and source, counted once. Missing ledger components are Cannot verify', Severity::Block, 1, false),
            new RuleDefinition('MI-02', 'Funding sources', 'model_integrity', ['model.opening_cash', 'funding.amount', 'funding.date', 'funding.restriction', 'model.available_funds'], 'Opening cash and each funding source reconcile to the available-funds total without duplication. Record source identity/type, commitment/evidence status, amount, availability date, restrictions and draw schedule; do not use a balancing plug or future funding to cover an earlier deficit', Severity::Block, 1, false),
            new RuleDefinition('MI-03', 'Fixed-cost schedules', 'model_integrity', ['cost.rate', 'cost.quantity', 'cost.frequency', 'cost.expense', 'cost.payment', 'model.fixed_cost'], 'Unrounded fixed-cost rates, units, frequencies and staged schedules reconcile to monthly expense and annual totals under the recorded rounding policy. Separately reconcile expense recognition to cash-payment dates; document permitted displayed rounding', Severity::Block, 1, false),
            new RuleDefinition('MI-04', 'Tax policy and timing', 'model_integrity', ['tax.policy', 'tax.profit', 'tax.loss', 'tax.expense', 'tax.payment'], 'Tax expense follows the stated entity/tax policy: eligible losses and explicit adjustments determine taxable profit; cash tax follows its separate due-date schedule. No automatic tax receipt is created by a loss. Missing applicable policy/schedule inputs are Cannot verify', Severity::Block, 1, false),
            new RuleDefinition('MI-05', 'Asset classification', 'model_integrity', ['cost.amount', 'cost.classification', 'cost.asset_like', 'cost.policy'], 'Asset-like expenditure at/above the $1,000 review threshold classified as operating cost receives classification review. Amount alone does not determine capex; apply a stated accounting policy, useful life and cash date', Severity::Review, 1, false),
            new RuleDefinition('MI-06', 'Required horizon', 'model_integrity', ['model.horizon', 'scope.required_horizon', 'scope.prior_required_horizon'], 'The model covers each period for which a financial outcome or funding sufficiency is claimed. Aspirational later activity may be separately labelled unmodelled; listing an explicitly excluded future commitment does not assert it is funded. Missing required periods cannot erase findings', Severity::Block, 1, false),
            new RuleDefinition('MI-07', 'Elapsed actuals', 'model_integrity', ['actuals.as_of', 'model.start_date', 'actuals.status', 'actuals.closing_cash', 'period.label', 'forecast.opening_cash'], 'At the release snapshot date, every elapsed reporting month has reconciled actuals or is explicitly established as pre-trading/not applicable. Actuals and forecasts have distinct labels and a checked cash handover; missing records are Cannot verify', Severity::Block, 2, true),
            new RuleDefinition('MI-08', 'Month 13 bridge', 'model_integrity', ['scope.required_horizon', 'stream.revenue', 'bridge.growth', 'bridge.seasonality', 'bridge.capacity_change', 'bridge.start_stop'], 'Where the required scope includes Month 13, reconcile its revenue to Month 12 by stream with growth, seasonality, capacity and starts/stops explained. Missing Month 13 is Cannot verify. Not applicable only when the legitimate scope has no Month 13 claim or requirement', Severity::Review, 2, false),
            new RuleDefinition('SS-01', 'Scenario reconciliation', 'scenario_sanity', ['scenario.baseline', 'scenario.shocks', 'scenario.cash', 'scenario.profit', 'scenario.bridge'], 'Scenario inputs use the same baseline, dates and opening balances with only declared shocks and documented dependent responses. Recompute the full cash ledger, profit and reported extrema; explain differences through a bridge of receipts, costs, tax, funding and timing. An unexplained result is Cannot verify or Fail if a mismatch is demonstrated. No universal ordering of lowest cash/profit is imposed', Severity::Block, 1, false),
            new RuleDefinition('SS-02', 'Stress dimensions', 'scenario_sanity', ['scenario.dimension', 'scenario.interval', 'scenario.requested_shock', 'scenario.effective_shock', 'scenario.shock_reduction_reason'], 'Validate each shock on its own defined input dimension and interval: revenue-downside volumes, cost-upside rates, slow-start quarter volumes, or collection-date delay. Show requested and effective shocks after capacity caps and actuals protection; flag ineffective/undersized stresses. Do not apply a 20% annual revenue test to a collections-delay or slow-start scenario', Severity::Review, 2, false),
            new RuleDefinition('SS-03', 'Scenario funding', 'scenario_sanity', ['scenario.lowest_cash', 'funding.basis', 'scenario.cash_deficit', 'scenario.reserve_gap', 'funding.worst_deficit_scenario', 'funding.worst_reserve_scenario', 'model.external_request', 'funding.request_metric', 'funding.request_basis_scenario', 'funding.non_external_total', 'funding.reserve_only_disclosure'], 'Calculate cash deficits and reserve-target shortfalls for every required scenario on the same declared basis. Identify the worst scenario separately for each metric; any proposed external request addresses the chosen requirement and its dates after named non-external sources, without double subtraction. A no-request decision with a reserve-only gap is disclosed, not converted automatically into debt', Severity::Block, 2, false),
            new RuleDefinition('DH-01', 'Internal instructions', 'document_hygiene', ['document.blocks'], 'No advisor-entry prompts or internal review instructions in the external-release artifact; allow them in clearly marked internal review copies', Severity::Block, 1, true),
            new RuleDefinition('DH-02', 'Unresolved placeholders', 'document_hygiene', ['document.blocks'], 'No unresolved update/superseded placeholders, runs of underscores, TBD or truncated-extract markers in release content. Legitimate draft notices are required on review copies and are not this rule\'s defect', Severity::Block, 1, false),
            new RuleDefinition('DH-03', 'Duplicate content', 'document_hygiene', ['document.blocks'], 'No duplicated headings or near-duplicate blocks within a document', Severity::Review, 1, false),
            new RuleDefinition('DH-04', 'Raw Markdown', 'document_hygiene', ['document.blocks'], 'No raw markdown artifacts in rendered text (for example asterisks)', Severity::Block, 1, false),
            new RuleDefinition('DH-05', 'Display conventions', 'document_hygiene', ['document.blocks'], 'Monetary amounts have unambiguous currency/units, plurals are correct and a shared display policy governs precision and dates. Distinguish display-style differences from mismatched values (NB-02)', Severity::Review, 1, false),
            new RuleDefinition('DH-06', 'Generated punctuation', 'document_hygiene', ['document.blocks'], 'System-generated text uses hyphens, not em dashes', Severity::Autofix, 1, false),
            new RuleDefinition('DH-07', 'Offer consistency', 'document_hygiene', ['document.blocks'], 'The same offer is described consistently across sections', Severity::Review, 3, false),
            new RuleDefinition('NB-01', 'Typed narrative binding', 'narrative_binding', ['plan.claims', 'budget.facts', 'evidence.records'], 'Every quantitative claim in generated narrative has a typed reference to a current model fact, historical record, source-backed claim or explicitly labelled founder assumption. Validate semantic field, entity, unit, period, scenario and provenance; matching an unrelated numeric value is insufficient. Missing binding metadata is Cannot verify', Severity::Block, 3, false),
            new RuleDefinition('NB-02', 'Cross-document values', 'narrative_binding', ['plan.claims', 'budget.facts', 'evidence.records'], 'The same financial metric, entity, period and scenario agrees across plan, brief and pack at the declared display precision, using a shared rounding policy. Consistent cents versus rounded dollars is Pass', Severity::Block, 3, false),
            new RuleDefinition('EV-01', 'Claim classification', 'evidence', ['plan.claims', 'budget.facts', 'evidence.records'], 'Every externally rendered claim maps to a versioned claim record with one of the four statuses and an auditable classifier. Unsupported claims cannot be promoted to Verified simply by attaching a file', Severity::Block, 4, false),
            new RuleDefinition('EV-02', 'Critical factual claims', 'evidence', ['plan.claims', 'budget.facts', 'evidence.records'], 'Each critical factual claim (registration, GST, insurance held, historical results, paid/completed work) has relevant supporting evidence with scope/status or an adjacent/scoped visible unverified label. A general endnote alone does not qualify every claim in a separate document', Severity::Block, 4, false),
            new RuleDefinition('EV-03', 'Assumption validation', 'evidence', ['plan.claims', 'budget.facts', 'evidence.records'], 'Sensitivity-ranked key assumptions have a basis, validation step, date and fail response, or an explicitly accepted missing-validation Review. Do not assume all founder assumptions lack a basis', Severity::Review, 4, false),
            new RuleDefinition('EV-04', 'Unsupported revenue share', 'evidence', ['plan.claims', 'budget.facts', 'evidence.records'], 'Calculate the union of Year 1 revenue exposed to Founder-stated/Founder assumption inputs missing a basis or test; count each stream-month once even if price and volume are both unsupported. Review above 50%; absent attribution data is Cannot verify, not 100% or zero', Severity::Review, 4, false),
            new RuleDefinition('EV-05', 'Evidence index', 'evidence', ['plan.claims', 'budget.facts', 'evidence.records'], 'Every claim has an index entry; cover counts reconcile to unique claim IDs and their current status. Source snapshots/links have access dates and permitted visibility; no private evidence leaks into exports', Severity::Block, 4, false),
        ];
    }

    public static function get(string $id): RuleDefinition
    {
        foreach (self::all() as $definition) {
            if ($definition->id === $id) {
                return $definition;
            }
        }
        throw new \InvalidArgumentException('Unknown release rule: '.$id);
    }
}
